createMarketStallMesh:
static createMarketStallMesh(
    _quality: "low" | "medium" | "high" = "medium",
    stallType = "fruit",
    stripeColor1 = "#e53935",
    stripeColor2 = "#ffffff"
  ): { group: THREE.Group; meshes: THREE.Mesh[] } {
    const group = new THREE.Group();
    const meshes: THREE.Mesh[] = [];

    const woodDeckMat = new THREE.MeshStandardMaterial({ color: 0x6d4c41, roughness: 0.6 });
    const woodPostMat = new THREE.MeshStandardMaterial({ color: 0x5d4037, roughness: 0.6 });
    const woodTableMat = new THREE.MeshStandardMaterial({ color: 0x8d6e63, roughness: 0.5 });
    const c1 = new THREE.MeshStandardMaterial({ color: new THREE.Color(stripeColor1), roughness: 0.4 });
    const c2 = new THREE.MeshStandardMaterial({ color: new THREE.Color(stripeColor2), roughness: 0.4 });
    const lanternMat = new THREE.MeshStandardMaterial({ color: 0xfff9c4, emissive: new THREE.Color(0xffd54f), emissiveIntensity: 0.8 });

    // 1. Solid Wooden Deck Platform (elevated stall floor)
    const deckGeo = new THREE.BoxGeometry(5.4, 0.3, 4.4);
    deckGeo.translate(0, 0.15, 0);
    const deck = new THREE.Mesh(deckGeo, woodDeckMat);
    group.add(deck);
    meshes.push(deck);

    // Deck perimeter wood curb
    const curbGeo = new THREE.BoxGeometry(5.6, 0.15, 4.6);
    curbGeo.translate(0, 0.075, 0);
    group.add(new THREE.Mesh(curbGeo, woodPostMat));

    // 2. 4 Timber Corner Posts with Diagonal Braces
    const postGeo = new THREE.BoxGeometry(0.22, 3.0, 0.22);
    const offsets = [
      [-2.45, -1.9],
      [2.45, -1.9],
      [-2.45, 1.9],
      [2.45, 1.9]
    ];
    for (const [px, pz] of offsets) {
      const post = new THREE.Mesh(postGeo, woodPostMat);
      post.position.set(px, 1.5, pz);
      group.add(post);
      meshes.push(post);
    }

    // Rear timber cross-braces & protective backdrop
    const rearBackGeo = new THREE.BoxGeometry(5.0, 2.4, 0.12);
    rearBackGeo.translate(0, 1.5, -1.95);
    const rearBack = new THREE.Mesh(rearBackGeo, woodPostMat);
    group.add(rearBack);
    meshes.push(rearBack);

    // 3. Market Counter Table & Display Shelves
    const tableGeo = new THREE.BoxGeometry(5.0, 0.22, 2.0);
    tableGeo.translate(0, 0.85, 0.3);
    const table = new THREE.Mesh(tableGeo, woodTableMat);
    group.add(table);
    meshes.push(table);

    const tableSkirtGeo = new THREE.BoxGeometry(5.0, 0.8, 0.1);
    tableSkirtGeo.translate(0, 0.4, -0.65);
    group.add(new THREE.Mesh(tableSkirtGeo, woodTableMat));

    // Rear upper display shelf
    const rearShelfGeo = new THREE.BoxGeometry(5.0, 0.15, 0.8);
    rearShelfGeo.translate(0, 1.4, -1.5);
    group.add(new THREE.Mesh(rearShelfGeo, woodTableMat));

    // 4. Striped Canvas Awning (8 alternating canopy stripes with slope)
    const numStripes = 8;
    const stripeW = 5.2 / numStripes;
    for (let i = 0; i < numStripes; i++) {
      const sGeo = new THREE.BoxGeometry(stripeW, 0.1, 4.4);
      sGeo.rotateX(0.20);
      sGeo.translate(-2.6 + stripeW / 2 + i * stripeW, 2.7, 0.0);
      const sMesh = new THREE.Mesh(sGeo, i % 2 === 0 ? c1 : c2);
      group.add(sMesh);
      meshes.push(sMesh);
    }

    // Scalloped Front Valance & Wooden Stall Signboard
    const valanceGeo = new THREE.BoxGeometry(5.2, 0.35, 0.08);
    valanceGeo.translate(0, 2.3, -2.15);
    group.add(new THREE.Mesh(valanceGeo, c1));

    const signGeo = new THREE.BoxGeometry(3.6, 0.5, 0.12);
    signGeo.translate(0, 3.1, -2.1);
    const signBoard = new THREE.Mesh(signGeo, woodPostMat);
    group.add(signBoard);

    // 4 Hanging Festoon Lanterns along the front
    for (const lx of [-2.0, -0.7, 0.7, 2.0]) {
      const cord = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.015, 0.35, 4), woodPostMat);
      cord.position.set(lx, 2.35, -2.05);
      group.add(cord);
      const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 8), lanternMat);
      bulb.position.set(lx, 2.15, -2.05);
      group.add(bulb);
    }

    // 5. Authentic, High-Detail 3D Merchandise Props
    if (stallType === "fruit") {
      const crateGeo = new THREE.BoxGeometry(1.2, 0.32, 0.8);
      const crateMat = new THREE.MeshStandardMaterial({ color: 0x795548, roughness: 0.6 });
      const leafMat = new THREE.MeshStandardMaterial({ color: 0x388e3c, roughness: 0.5 });
      for (let c = -1; c <= 1; c++) {
        const crate = new THREE.Mesh(crateGeo, crateMat);
        crate.rotation.x = -0.15; // Slanted display toward customer
        crate.position.set(c * 1.5, 1.05, 0.3);
        group.add(crate);

        const fruitMat = new THREE.MeshStandardMaterial({
          color: c === -1 ? 0xff9800 : (c === 0 ? 0xffeb3b : 0x4caf50),
          roughness: 0.35
        });
        for (let fx = -0.4; fx <= 0.4; fx += 0.35) {
          for (let fz = -0.25; fz <= 0.25; fz += 0.35) {
            const fruit = new THREE.Mesh(new THREE.SphereGeometry(0.13, 8, 8), fruitMat);
            fruit.position.set(c * 1.5 + fx, 1.25, 0.3 + fz);
            group.add(fruit);
            if (fx === 0 && fz === 0) {
              const stem = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.08, 0.08), leafMat);
              stem.position.set(c * 1.5, 1.4, 0.3);
              group.add(stem);
            }
          }
        }
      }
      for (const rx of [-1.5, 0, 1.5]) {
        const melon = new THREE.Mesh(new THREE.SphereGeometry(0.28, 8, 8), new THREE.MeshStandardMaterial({ color: 0x2e7d32 }));
        melon.scale.set(1.0, 0.8, 1.3);
        melon.position.set(rx, 1.68, -1.5);
        group.add(melon);
      }
    } else if (stallType === "pottery") {
      const clayMat = new THREE.MeshStandardMaterial({ color: 0xd84315, roughness: 0.4 });
      const blueCeramicMat = new THREE.MeshStandardMaterial({ color: 0x0288d1, roughness: 0.25 });
      for (const vx of [-1.7, -0.6, 0.6, 1.7]) {
        const vase = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.14, 0.65, 12), clayMat);
        vase.position.set(vx, 1.28, 0.3);
        group.add(vase);
      }
      for (const px of [-1.5, 0, 1.5]) {
        const plate = new THREE.Mesh(new THREE.CylinderGeometry(0.38, 0.38, 0.04, 16), blueCeramicMat);
        plate.rotation.x = Math.PI / 2.5;
        plate.position.set(px, 1.85, -1.5);
        group.add(plate);
      }
    } else if (stallType === "hats") {
      const strawMat = new THREE.MeshStandardMaterial({ color: 0xffe082, roughness: 0.5 });
      const ribbonMat = new THREE.MeshStandardMaterial({ color: 0xd32f2f, roughness: 0.4 });
      for (const hx of [-1.5, 0, 1.5]) {
        const stand = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.55, 6), woodPostMat);
        stand.position.set(hx, 1.2, 0.3);
        group.add(stand);
        const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.48, 0.48, 0.04, 12), strawMat);
        brim.position.set(hx, 1.48, 0.3);
        group.add(brim);
        const crown = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.24, 0.22, 12), strawMat);
        crown.position.set(hx, 1.6, 0.3);
        group.add(crown);
        const ribbon = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.25, 0.06, 12), ribbonMat);
        ribbon.position.set(hx, 1.52, 0.3);
        group.add(ribbon);
      }
      for (const bx of [-1.2, 1.2]) {
        const bag = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.5, 0.25), strawMat);
        bag.position.set(bx, 1.72, -1.5);
        group.add(bag);
      }
    } else if (stallType === "flowers") {
      const flowerColors = [0xe91e63, 0xab47bc, 0xffee58, 0x26c6da];
      for (let f = 0; f < 4; f++) {
        const bucket = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.18, 0.45, 10), woodTableMat);
        bucket.position.set(-1.8 + f * 1.2, 1.18, 0.3);
        group.add(bucket);
        const bloom = new THREE.Mesh(new THREE.SphereGeometry(0.28, 8, 8), new THREE.MeshStandardMaterial({ color: flowerColors[f] }));
        bloom.position.set(-1.8 + f * 1.2, 1.52, 0.3);
        group.add(bloom);
      }
      for (const lx of [-1.4, 0, 1.4]) {
        const pot = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.14, 0.3, 8), new THREE.MeshStandardMaterial({ color: 0xbf360c }));
        pot.position.set(lx, 1.62, -1.5);
        group.add(pot);
        const lavender = new THREE.Mesh(new THREE.SphereGeometry(0.22, 6, 6), new THREE.MeshStandardMaterial({ color: 0x7e57c2 }));
        lavender.position.set(lx, 1.85, -1.5);
        group.add(lavender);
      }
    } else if (stallType === "goal") {
      const goldMat = new THREE.MeshStandardMaterial({ color: 0xffd54f, roughness: 0.2, metalness: 0.85 });
      const redVelvetMat = new THREE.MeshStandardMaterial({ color: 0xb71c1c, roughness: 0.6 });

      // Red carpet runner down the stall
      const carpet = new THREE.Mesh(new THREE.BoxGeometry(2.4, 0.04, 3.8), redVelvetMat);
      carpet.position.set(0, 0.32, 0);
      group.add(carpet);

      // Golden Stanchions
      for (const [sx, sz] of [[-1.3, -1.2], [1.3, -1.2], [-1.3, 1.2], [1.3, 1.2]]) {
        const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 1.0, 8), goldMat);
        pole.position.set(sx, 0.8, sz);
        const ball = new THREE.Mesh(new THREE.SphereGeometry(0.09, 8, 8), goldMat);
        ball.position.set(sx, 1.35, sz);
        group.add(pole, ball);
      }

      // Monumental Golden Pedestal for Goal
      const ped = new THREE.Mesh(new THREE.CylinderGeometry(1.0, 1.25, 0.7, 16), goldMat);
      ped.position.set(0, 0.7, 0.3);
      group.add(ped);
      meshes.push(ped);
    }

    return { group, meshes };
  }

createShopMesh:
static createShopMesh(
    _quality: "low" | "medium" | "high" = "medium",
    shopType = "icecream",
    customColor = "#00bcd4"
  ): { group: THREE.Group; meshes: THREE.Mesh[] } {
    const group = new THREE.Group();
    const meshes: THREE.Mesh[] = [];

    const wallMat = new THREE.MeshStandardMaterial({ color: 0xf5f5f5, roughness: 0.4 });
    const floorMat = new THREE.MeshStandardMaterial({ color: 0xd7ccc8, roughness: 0.4 });
    const frameMat = new THREE.MeshStandardMaterial({ color: 0x37474f, roughness: 0.3 });
    const glassMat = new THREE.MeshStandardMaterial({ color: 0x81d4fa, roughness: 0.1, transparent: true, opacity: 0.4 });
    const signMat = new THREE.MeshStandardMaterial({ color: new THREE.Color(customColor), roughness: 0.3 });
    const neonMat = new THREE.MeshStandardMaterial({ color: new THREE.Color(customColor), emissive: new THREE.Color(customColor), emissiveIntensity: 0.8 });

    // 1. Shop Floor
    const floorGeo = new THREE.BoxGeometry(7.2, 0.2, 7.2);
    floorGeo.translate(0, 0.1, 0);
    const floor = new THREE.Mesh(floorGeo, floorMat);
    group.add(floor);
    meshes.push(floor);

    // 2. Back and Side Enclosing Walls
    const backGeo = new THREE.BoxGeometry(7.2, 3.8, 0.3);
    backGeo.translate(0, 2.0, -3.45);
    const backWall = new THREE.Mesh(backGeo, wallMat);
    group.add(backWall);
    meshes.push(backWall);

    const wallLGeo = new THREE.BoxGeometry(0.3, 3.8, 7.2);
    wallLGeo.translate(-3.45, 2.0, 0);
    const wallL = new THREE.Mesh(wallLGeo, wallMat);
    group.add(wallL);
    meshes.push(wallL);

    const wallRGeo = new THREE.BoxGeometry(0.3, 3.8, 7.2);
    wallRGeo.translate(3.45, 2.0, 0);
    const wallR = new THREE.Mesh(wallRGeo, wallMat);
    group.add(wallR);
    meshes.push(wallR);

    // 3. Storefront Glass & Lintel
    const lintelGeo = new THREE.BoxGeometry(7.2, 0.8, 0.3);
    lintelGeo.translate(0, 3.5, 3.45);
    const lintel = new THREE.Mesh(lintelGeo, frameMat);
    group.add(lintel);
    meshes.push(lintel);

    const winL = new THREE.Mesh(new THREE.BoxGeometry(2.3, 2.7, 0.1), glassMat);
    winL.position.set(-2.3, 1.45, 3.45);
    group.add(winL);
    const winR = new THREE.Mesh(new THREE.BoxGeometry(2.3, 2.7, 0.1), glassMat);
    winR.position.set(2.3, 1.45, 3.45);
    group.add(winR);

    // 4. Store Fascia Signboard with 3D Emblem
    const signGeo = new THREE.BoxGeometry(5.6, 0.7, 0.25);
    signGeo.translate(0, 3.6, 3.6);
    group.add(new THREE.Mesh(signGeo, signMat));

    if (shopType === "icecream") {
      const cone = new THREE.Mesh(new THREE.ConeGeometry(0.25, 0.5, 8), new THREE.MeshStandardMaterial({ color: 0xffb74d }));
      cone.rotateX(Math.PI);
      cone.position.set(0, 4.1, 3.75);
      group.add(cone);
      const scoop = new THREE.Mesh(new THREE.SphereGeometry(0.28, 8, 8), neonMat);
      scoop.position.set(0, 4.4, 3.75);
      group.add(scoop);

      const freezer = new THREE.Mesh(new THREE.BoxGeometry(3.6, 0.9, 1.4), new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.2 }));
      freezer.position.set(0, 0.55, 0.5);
      group.add(freezer);
      meshes.push(freezer);
    } else if (shopType === "surf") {
      const boardSign = new THREE.Mesh(new THREE.BoxGeometry(1.6, 0.4, 0.08), neonMat);
      boardSign.position.set(0, 4.3, 3.75);
      group.add(boardSign);

      const rack = new THREE.Mesh(new THREE.BoxGeometry(0.2, 2.2, 2.4), frameMat);
      rack.position.set(-2.2, 1.2, 0);
      group.add(rack);
      meshes.push(rack);

      const boardColors = [0x00e5ff, 0xffeb3b, 0xff1744];
      for (let b = 0; b < 3; b++) {
        const sb = new THREE.Mesh(new THREE.BoxGeometry(0.08, 2.0, 0.6), new THREE.MeshStandardMaterial({ color: boardColors[b] }));
        sb.position.set(-2.0, 1.2, -0.7 + b * 0.7);
        group.add(sb);
      }
    } else if (shopType === "arcade") {
      const cabGeo = new THREE.BoxGeometry(1.1, 2.2, 1.1);
      const cabMat = new THREE.MeshStandardMaterial({ color: 0x212121, roughness: 0.4 });
      const screenMat = new THREE.MeshStandardMaterial({ color: 0x00e5ff, emissive: 0x00e5ff, emissiveIntensity: 0.8 });

      for (const ax of [-1.5, 1.5]) {
        const cab = new THREE.Mesh(cabGeo, cabMat);
        cab.position.set(ax, 1.2, -1.5);
        group.add(cab);
        meshes.push(cab);

        const screen = new THREE.Mesh(new THREE.PlaneGeometry(0.8, 0.6), screenMat);
        screen.position.set(ax, 1.5, -0.94);
        group.add(screen);
      }
    } else if (shopType === "bakery") {
      const counter = new THREE.Mesh(new THREE.BoxGeometry(3.6, 0.9, 1.4), new THREE.MeshStandardMaterial({ color: 0x8d6e63 }));
      counter.position.set(0, 0.55, 0.5);
      group.add(counter);
      meshes.push(counter);

      const coffee = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.6, 0.6), new THREE.MeshStandardMaterial({ color: 0xb0bec5, metalness: 0.8 }));
      coffee.position.set(-1.0, 1.3, 0.5);
      group.add(coffee);
    } else if (shopType === "fashion") {
      const pod = new THREE.Mesh(new THREE.CylinderGeometry(0.8, 0.8, 0.3, 16), new THREE.MeshStandardMaterial({ color: 0xffffff }));
      pod.position.set(-1.5, 0.25, 0.5);
      group.add(pod);
      meshes.push(pod);

      const mannequin = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.18, 1.6, 8), neonMat);
      mannequin.position.set(-1.5, 1.2, 0.5);
      group.add(mannequin);
    } else if (shopType === "jewelry") {
      const goldMat = new THREE.MeshStandardMaterial({ color: 0xffd54f, roughness: 0.25, metalness: 0.8 });
      const vipPed = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 1.1, 0.5, 16), goldMat);
      vipPed.position.set(0, 0.35, 0.0);
      group.add(vipPed);
      meshes.push(vipPed);

      const caseL = new THREE.Mesh(new THREE.BoxGeometry(0.8, 1.2, 0.8), new THREE.MeshStandardMaterial({ color: 0x512da8 }));
      caseL.position.set(-2.0, 0.7, -1.5);
      group.add(caseL);
      meshes.push(caseL);
      const caseR = caseL.clone();
      caseR.position.x = 2.0;
      group.add(caseR);
      meshes.push(caseR);
    }

    return { group, meshes };
  }

createVerticalWheelMesh:
static createVerticalWheelMesh(
    radius = 3.5,
    width = 2.4,
    _quality: "low" | "medium" | "high" = "medium"
  ): { group: THREE.Group; meshes: THREE.Mesh[]; topTreadMesh: THREE.Mesh } {
    const group = new THREE.Group();
    const meshes: THREE.Mesh[] = [];

    const tireMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.7 });
    const yellowTreadMat = new THREE.MeshStandardMaterial({ color: 0xffd600, roughness: 0.4 });
    const rimMat = new THREE.MeshStandardMaterial({ color: 0xe0e0e0, roughness: 0.2, metalness: 0.85 });
    const hubMat = new THREE.MeshStandardMaterial({ color: 0x37474f, roughness: 0.3, metalness: 0.7 });
    const spokeMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.15, metalness: 0.9 });
    const reflectorMat = new THREE.MeshStandardMaterial({ color: 0xff6d00, roughness: 0.3, emissive: new THREE.Color(0xff6d00), emissiveIntensity: 0.35 });
    const brassMat = new THREE.MeshStandardMaterial({ color: 0xffb300, roughness: 0.3, metalness: 0.8 });

    // 1. Outer Hollow Rubber Tire Tube (open ended along X)
    const tireGeo = new THREE.CylinderGeometry(radius, radius, width, 36, 1, true);
    tireGeo.rotateZ(Math.PI / 2);
    const tire = new THREE.Mesh(tireGeo, tireMat);
    group.add(tire);
    meshes.push(tire);

    // Inner tire wall
    const innerTireGeo = new THREE.CylinderGeometry(radius - 0.35, radius - 0.35, width, 36, 1, true);
    innerTireGeo.rotateZ(Math.PI / 2);
    group.add(new THREE.Mesh(innerTireGeo, tireMat));

    // 2. High-visibility chunky rubber tread blocks around circumference (16 alternating blocks)
    const numTreads = 16;
    for (let i = 0; i < numTreads; i++) {
      const angle = (i * Math.PI * 2) / numTreads;
      const isYellow = i % 2 === 0;
      const tGeo = new THREE.BoxGeometry(width + 0.08, 0.22, 0.45);
      tGeo.translate(0, radius, 0);
      tGeo.rotateX(angle);
      const tMesh = new THREE.Mesh(tGeo, isYellow ? yellowTreadMat : tireMat);
      group.add(tMesh);
      meshes.push(tMesh);
    }

    // Top collision tread mesh
    const topTreadGeo = new THREE.BoxGeometry(width, 0.4, 3.2);
    topTreadGeo.translate(0, radius - 0.1, 0);
    const topTreadMesh = new THREE.Mesh(topTreadGeo, tireMat);
    group.add(topTreadMesh);
    meshes.push(topTreadMesh);

    // 3. Hollow Silver Alloy Rims (Left and Right flanges as Toruses so you can see right through the wheel!)
    const rimRadius = radius - 0.42;
    const rimTube = 0.16;
    for (const rx of [-width / 2 + 0.1, width / 2 - 0.1]) {
      const rimTorus = new THREE.Mesh(new THREE.TorusGeometry(rimRadius, rimTube, 12, 36), rimMat);
      rimTorus.rotateY(Math.PI / 2);
      rimTorus.position.x = rx;
      group.add(rimTorus);
      meshes.push(rimTorus);
    }

    // 4. Central Hub Axle
    const hubGeo = new THREE.CylinderGeometry(0.48, 0.48, width + 0.4, 16);
    hubGeo.rotateZ(Math.PI / 2);
    group.add(new THREE.Mesh(hubGeo, hubMat));

    // Axle nuts on both ends
    for (const nx of [-width / 2 - 0.25, width / 2 + 0.25]) {
      const nut = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.25, 0.15, 6), brassMat);
      nut.rotateZ(Math.PI / 2);
      nut.position.x = nx;
      group.add(nut);
    }

    // 5. Radial Metallic Spokes (20 pairs)
    const numSpokes = 20;
    const spokeLen = radius - 0.5;
    for (let i = 0; i < numSpokes; i++) {
      const angle = (i * Math.PI * 2) / numSpokes;
      const sGeo = new THREE.CylinderGeometry(0.035, 0.035, spokeLen, 6);
      sGeo.translate(0, spokeLen / 2, 0);
      sGeo.rotateX(angle);

      const spokeL = new THREE.Mesh(sGeo, spokeMat);
      spokeL.position.x = -width / 2 + 0.12;
      group.add(spokeL);

      const spokeR = new THREE.Mesh(sGeo, spokeMat);
      spokeR.position.x = width / 2 - 0.12;
      group.add(spokeR);

      // Spoke Reflectors at 90° and 270°
      if (i === 5 || i === 15) {
        const refGeo = new THREE.BoxGeometry(0.12, 0.38, 0.18);
        refGeo.translate(0, spokeLen * 0.55, 0);
        refGeo.rotateX(angle);
        const refL = new THREE.Mesh(refGeo, reflectorMat);
        refL.position.x = -width / 2 + 0.12;
        group.add(refL);
        const refR = new THREE.Mesh(refGeo, reflectorMat);
        refR.position.x = width / 2 - 0.12;
        group.add(refR);
      }
    }

    // 6. Brass Valve Stem
    const valve = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 0.35, 8), brassMat);
    valve.position.set(0, radius - 0.55, 0);
    group.add(valve);

    return { group, meshes, topTreadMesh };
  }

getEMTBusDestinationTexture:
static getEMTBusDestinationTexture(line: string = "35", dest?: string): THREE.CanvasTexture {
    const key = `${line}_${dest || ""}`;
    const cached = this.emtBusDestMap.get(key);
    if (cached) return cached;

    if (typeof document === "undefined") {
      const dummyTex = new THREE.CanvasTexture({} as any);
      this.emtBusDestMap.set(key, dummyTex);
      return dummyTex;
    }

    try {
      const canvas = document.createElement("canvas");
      canvas.width = 512;
      canvas.height = 128;
      const ctx = canvas.getContext("2d");
      if (ctx) {
        ctx.fillStyle = "#0c1017";
        ctx.fillRect(0, 0, 512, 128);

        // EMT Blue route badge
        ctx.fillStyle = "#0072ce";
        if (typeof ctx.roundRect === "function") {
          ctx.beginPath();
          ctx.roundRect(14, 14, 90, 100, 14);
          ctx.fill();
        } else {
          ctx.fillRect(14, 14, 90, 100);
