          { x: 50, y: 95, r: 7, c: "#fed7aa", center: "#c2410c" },
          { x: 125, y: 85, r: 9, c: "#ffffff", center: "#f59e0b" },
          { x: 190, y: 105, r: 7, c: "#fbcfe8", center: "#e11d48" },
          { x: 35, y: 160, r: 8, c: "#ffffff", center: "#f59e0b" },
