          { x: 205, y: 220, r: 8, c: "#ffffff", center: "#f59e0b" },
        ];

        flowers.forEach(f => {
          // Petals (5 petals around center)
          ctx.fillStyle = f.c;
          for (let p = 0; p < 5; p++) {
            const angle = (p * Math.PI * 2) / 5;
            const px = f.x + Math.cos(angle) * (f.r * 0.7);
            const py = f.y + Math.sin(angle) * (f.r * 0.7);
            ctx.beginPath();
            ctx.arc(px, py, f.r * 0.55, 0, Math.PI * 2);
