        for (let i = 0; i < 40; i++) {
          const x = 30 + (i * 12.3) % 452;
          ctx.fillRect(x, 0, 1.8, 512);
        }

        // Papillae (filiform & fungiform taste buds)
        for (let i = 0; i < 500; i++) {
          const px = (i * 97) % 512;
          const py = (i * 149) % 512;
