    for (const ex of [-0.09, 0.09]) {
      const eye = new THREE.Mesh(new THREE.SphereGeometry(0.035, 6, 6), eyeMat);
      eye.position.set(ex, 0.58, -0.36);
      group.add(eye);
      meshes.push(eye);
    }

    // 4. Ears according to animalType
    if (animalType === "rabbit") {
      for (const ex of [-0.09, 0.09]) {
        const ear = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.06, 0.32, 6), plushMat);
        ear.rotation.z = ex > 0 ? -0.2 : 0.2;
        ear.position.set(ex, 0.82, -0.12);
        group.add(ear);
        meshes.push(ear);
      }
    } else {
      // Teddy bear ears
      for (const ex of [-0.18, 0.18]) {
        const ear = new THREE.Mesh(new THREE.SphereGeometry(0.1, 6, 6), plushMat);
        ear.position.set(ex, 0.72, -0.12);
        group.add(ear);
        meshes.push(ear);
      }
    }

    // 5. Little paws
    for (const px of [-0.28, 0.28]) {
      const paw = new THREE.Mesh(new THREE.SphereGeometry(0.12, 6, 6), plushMat);
      paw.position.set(px, 0.16, 0.12);
      group.add(paw);
      meshes.push(paw);
    }

    return { group, meshes };
  }

createFunkoBoxMesh:
static createFunkoBoxMesh(
    width = 4.2,
    height = 5.2,
    depth = 3.8,
    _quality: "low" | "medium" | "high" = "medium"
  ): { group: THREE.Group; meshes: THREE.Mesh[] } {
    const group = new THREE.Group();
    group.name = "funko_pop_box_group";
    const meshes: THREE.Mesh[] = [];

    const whiteCardMat = new THREE.MeshStandardMaterial({ color: 0xf8fafc, roughness: 0.35 });
    const blueHeaderMat = new THREE.MeshStandardMaterial({ color: 0x0288d1, roughness: 0.35 });
    const vinylSkinMat = new THREE.MeshStandardMaterial({ color: 0xffcc80, roughness: 0.4 });
    const vinylHeroMat = new THREE.MeshStandardMaterial({ color: 0xd32f2f, roughness: 0.35 });
    const vinylEyeMat = new THREE.MeshStandardMaterial({ color: 0x0d1117, roughness: 0.1 });

    // 1. Box Solid Core & Shell
    const boxCore = new THREE.Mesh(new THREE.BoxGeometry(width, height, depth), whiteCardMat);
    boxCore.position.set(0, height / 2, 0);
    group.add(boxCore);
    meshes.push(boxCore);

    // 2. Top and Bottom Header/Footer Trims
    const topCap = new THREE.Mesh(new THREE.BoxGeometry(width + 0.08, 0.9, depth + 0.08), blueHeaderMat);
    topCap.position.set(0, height - 0.45, 0);
    const bottomCap = new THREE.Mesh(new THREE.BoxGeometry(width + 0.08, 0.8, depth + 0.08), blueHeaderMat);
    bottomCap.position.set(0, 0.4, 0);
    group.add(topCap, bottomCap);
    meshes.push(topCap, bottomCap);

    // 3. Front Window Art Face (Textured Funko Graphic)
    const boxTex = SpriteTextures.getFunkoBoxTexture();
    const frontFaceMat = new THREE.MeshStandardMaterial({ map: boxTex, roughness: 0.3 });
    const frontFace = new THREE.Mesh(new THREE.PlaneGeometry(width * 0.98, height * 0.98), frontFaceMat);
    frontFace.position.set(0, height / 2, depth / 2 + 0.05);
    group.add(frontFace);
    meshes.push(frontFace);

    // 4. Stylized 3D Vinyl Toy inside the window
    const head = new THREE.Mesh(new THREE.BoxGeometry(1.6, 1.4, 1.3), vinylSkinMat);
    head.position.set(0, height * 0.58, 0.2);
    for (const ex of [-0.42, 0.42]) {
      const eye = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.22, 0.06, 12), vinylEyeMat);
      eye.rotation.x = Math.PI / 2;
      eye.position.set(ex, height * 0.58, 0.88);
      group.add(eye);
      meshes.push(eye);
    }
    const body = new THREE.Mesh(new THREE.BoxGeometry(1.1, 1.2, 0.9), vinylHeroMat);
    body.position.set(0, height * 0.32, 0.2);
    group.add(head, body);
    meshes.push(head, body);

    return { group, meshes };
  }

createRodillaSandwichMesh:
static createRodillaSandwichMesh(
